Here is the problem description:
<problem_description>
All bus tickets in Berland have their numbers. A number consists of $$$n$$$ digits ($$$n$$$ is even). Only $$$k$$$ decimal digits $$$d_1, d_2, \dots, d_k$$$ can be used to form ticket numbers. If $$$0$$$ is among these digits, then numbers may have leading zeroes. For example, if $$$n = 4$$$ and only digits $$$0$$$ and $$$4$$$ can be used, then $$$0000$$$, $$$4004$$$, $$$4440$$$ are valid ticket numbers, and $$$0002$$$, $$$00$$$, $$$44443$$$ are not.A ticket is lucky if the sum of first $$$n / 2$$$ digits is equal to the sum of remaining $$$n / 2$$$ digits. Calculate the number of different lucky tickets in Berland. Since the answer may be big, print it modulo $$$998244353$$$.
</problem_description>

Here is the Java 8 code you have to repair:
<original_code>
import java.util.Scanner;

public class LuckyTickets {

    private static final int MOD = 998244353;
    private static final int TWO_POW = 23;
    private static final int ROOT = 15311432;

    private static int reverseBits(int x, int bits) {
        return Integer.reverse(x) >>> (32 - bits);
    }

    private static long powMod(long base, long exp) {
        long res = 1;
        base %= MOD;
        while (exp > 0) {
            if ((exp & 1) == 1) res = (res * base) % MOD;
            base = (base * base) % MOD;
            exp >>= 1;
        }
        return res;
    }

    private static long modInv(long a) {
        return powMod(a, MOD - 2);
    }

    private static long[] getRoots(int k, boolean inverse) {
        long root = powMod(ROOT, powMod(2, TWO_POW - k));
        if (inverse) root = modInv(root);
        long[] r = new long[k];
        r[k - 1] = root;
        for (int i = k - 1; i > 0; i--) {
            r[i - 1] = (r[i] * r[i]) % MOD;
        }
        return r;
    }

    private static long[] bitReverseArray(long[] arr, int k) {
        long[] res = new long[arr.length];
        for (int i = 0; i < arr.length; i++) {
            res[reverseBits(i, k)] = arr[i];
        }
        return res;
    }

    private static long[] nttTransform(long[] coef, int k, boolean inverse) {
        coef = bitReverseArray(coef, k);
        long[] roots = getRoots(k, inverse);
        for (int s = 0; s < k; s++) {
            int len = 1 << s;
            for (int st = 0; st < coef.length; st += 2 * len) {
                long w = 1;
                for (int j = st; j < st + len; j++) {
                    long t = (w * coef[j + len]) % MOD;
                    long u = coef[j];
                    coef[j] = (u + t) % MOD;
                    coef[j + len] = (u - t) % MOD;
                    w = (roots[s] * w) % MOD;
                }
            }
        }
        return coef;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt() / 2;
        int m = sc.nextInt();
        int[] arr = new int[m];
        int maxVal = 0;
        for (int i = 0; i < m; i++) {
            arr[i] = sc.nextInt();
            maxVal = Math.max(maxVal, arr[i]);
        }
        int reqSize = n * maxVal + 1;
        int k = 0, size = 1;
        while (size < reqSize) {
            size <<= 1;
            k++;
        }
        long[] poly = new long[size];
        for (int val : arr) {
            poly[val] = 1;
        }
        poly = nttTransform(poly, k, false);
        for (int i = 0; i < size; i++) {
            poly[i] = powMod(poly[i], n);
        }
        poly = nttTransform(poly, k, true);
        long sum = 0;
        for (int i = 0; i < size; i++) {
            sum = (sum + poly[i] * poly[i]) % MOD;
        }
        long invSize = modInv(size);
        System.out.println(((sum * invSize % MOD) * invSize) % MOD);
    }
}
